describe('User Registration', () => {
    beforeEach(() => {
        cy.visit('/register');
    });

    it('should display an error message for already-used email', () => {
        const usedEmail = 'test@example.com';

        // Simulate registration with an already-used email
        cy.get('input[name="email"]').type(usedEmail);
        cy.get('input[name="password"]').type('Password123');
        cy.get('input[name="confirmPassword"]').type('Password123');
        cy.get('button[type="submit"]').click();

        // Assert that the error message is displayed
        cy.get('.error-message').should('be.visible')
            .and('contain', 'Email is already in use');
    });

    it('should not allow registration with an invalid email format', () => {
        const invalidEmail = 'invalid-email-format';

        // Simulate registration with an invalid email format
        cy.get('input[name="email"]').type(invalidEmail);
        cy.get('input[name="password"]').type('Password123');
        cy.get('input[name="confirmPassword"]').type('Password123');
        cy.get('button[type="submit"]').click();

        // Assert that the error message is displayed
        cy.get('.error-message').should('be.visible')
            .and('contain', 'Please enter a valid email address');
    });
});
